import tushare as ts
import os
import pandas as pd
import math

token = os.environ.get('TUSHARE_TOKEN', '')
pro = ts.pro_api(token)

# 参数
trade_date = '20260213'
r = 0.02  # 无风险利率

# Black-Scholes 函数
def norm_cdf(x):
    return 0.5 * (1 + math.erf(x / math.sqrt(2)))

def bs_call(S, K, T, r, sigma):
    if T <= 0 or sigma <= 0:
        return max(S - K, 0)
    d1 = (math.log(S/K) + (r + 0.5*sigma**2)*T) / (sigma*math.sqrt(T))
    d2 = d1 - sigma*math.sqrt(T)
    return S * math.exp(-r*T) * norm_cdf(d1) - K * math.exp(-r*T) * norm_cdf(d2)

def bs_put(S, K, T, r, sigma):
    if T <= 0 or sigma <= 0:
        return max(K - S, 0)
    d1 = (math.log(S/K) + (r + 0.5*sigma**2)*T) / (sigma*math.sqrt(T))
    d2 = d1 - sigma*math.sqrt(T)
    return K * math.exp(-r*T) * norm_cdf(-d2) - S * math.exp(-r*T) * norm_cdf(-d1)

def implied_vol(price, S, K, T, r, opt_type='call'):
    if T <= 0:
        return 0
    low, high = 0.001, 2.0
    for _ in range(50):
        mid = (low + high) / 2
        if opt_type == 'call':
            model_price = bs_call(S, K, T, r, mid)
        else:
            model_price = bs_put(S, K, T, r, mid)

        if model_price > price:
            high = mid
        else:
            low = mid
    return (low + high) / 2

# 获取期权价格
def get_price(ts_code, trade_date):
    try:
        d = pro.opt_daily(ts_code=ts_code, trade_date=trade_date)
        if len(d) > 0:
            return d.iloc[0]['close']
    except:
        pass
    return None

# 获取300ETF 3月合约
df = pro.opt_basic(exchange='SSE', opt_type='ETF', limit=500)
hs300_03 = df[(df['name'].str.contains('沪深300', na=False)) & (df['s_month'] == '202603')]

calls = hs300_03[hs300_03['call_put'] == 'C'].sort_values('exercise_price')
puts = hs300_03[hs300_03['call_put'] == 'P'].sort_values('exercise_price')

# 获取价格
prices = {}
for idx, row in calls.iterrows():
    K = row['exercise_price']
    call_price = get_price(row['ts_code'], trade_date)
    prices[(K, 'C')] = call_price

    p = puts[puts['exercise_price'] == K]
    if len(p) > 0:
        put_price = get_price(p.iloc[0]['ts_code'], trade_date)
        prices[(K, 'P')] = put_price

# 到期时间 (3月26日到期)
T = 40/365  # 约40天

# 使用看跌-看涨平价反推标的资产价格
# 取虚值看涨期权和虚值看跌期权的平均值
# S = C + K*e^(-rT) - P

# 用几个不同行权价反推
S_estimates = []
for K in [3.996, 4.2, 4.288]:
    C = prices.get((K, 'C'))
    P = prices.get((K, 'P'))
    if C and P:
        S_est = C + K * math.exp(-r * T) - P
        S_estimates.append(S_est)
        print(f"K={K}: C={C}, P={P}, S_est={S_est:.4f}")

if S_estimates:
    S = sum(S_estimates) / len(S_estimates)
    print(f"\n估算的标的资产价格 S = {S:.4f}")
else:
    S = 4.2  # 默认值
    print(f"\n使用默认 S = {S:.4f}")

# 计算隐含波动率
print(f"\n=== 隐含波动率计算 ===")
print(f"标的资产价格 S = {S:.4f}")
print(f"到期时间 T = {T*365:.0f} 天")
print(f"无风险利率 r = {r*100}%")
print(f"\n{'行权价':<8}{'认购IV':<12}{'认沽IV':<12}{'IV平均值':<12}")
print("-" * 45)

ivs = []
for K in sorted(set([row['exercise_price'] for _, row in calls.iterrows()])):
    C = prices.get((K, 'C'))
    P = prices.get((K, 'P'))

    iv_call = None
    iv_put = None

    if C and C > 0.001:
        try:
            iv_call = implied_vol(C, S, K, T, r, 'call')
        except:
            pass

    if P and P > 0.001:
        try:
            iv_put = implied_vol(P, S, K, T, r, 'put')
        except:
            pass

    if iv_call or iv_put:
        avg_iv = (iv_call if iv_call else 0 + iv_put if iv_put else 0) / 2
        if avg_iv > 0:
            ivs.append(avg_iv)

        print(f"{K:<8}{f'{iv_call*100:.1f}%' if iv_call else 'N/A':<12}{f'{iv_put*100:.1f}%' if iv_put else 'N/A':<12}{f'{avg_iv*100:.1f}%' if avg_iv else 'N/A':<12}")

if ivs:
    avg_iv_all = sum(ivs) / len(ivs)
    print(f"\n平均隐含波动率: {avg_iv_all*100:.1f}%")
